+    <script>
+      (function () {
+        const root = document.documentElement;
+
+        // Mobile menu (interaction: mobile-menu-toggle)
+        const toggleBtn = document.querySelector('[data-mobile-toggle]');
+        const closeBtn = document.querySelector('[data-mobile-close]');
+        const backdrop = document.querySelector('[data-drawer-backdrop]');
+        const drawerLinks = Array.from(document.querySelectorAll('[data-drawer-link]'));
+        const focusableSelector =
+          'a[href], button:not([disabled]), input, select, textarea, [tabindex]:not([tabindex="-1"])';
+        let lastActive = null;
+
+        function setDrawerOpen(open) {
+          if (!toggleBtn) return;
+          if (open) {
+            lastActive = document.activeElement;
+            root.classList.add('drawer-open');
+            toggleBtn.setAttribute('aria-expanded', 'true');
+            const drawer = document.getElementById('mobile-drawer');
+            const focusables = drawer ? Array.from(drawer.querySelectorAll(focusableSelector)) : [];
+            (focusables[0] || closeBtn || drawer)?.focus?.();
+            document.body.style.overflow = 'hidden';
+          } else {
+            root.classList.remove('drawer-open');
+            toggleBtn.setAttribute('aria-expanded', 'false');
+            document.body.style.overflow = '';
+            if (lastActive && lastActive.focus) lastActive.focus();
+            lastActive = null;
+          }
+        }
+
+        toggleBtn?.addEventListener('click', () => setDrawerOpen(true));
+        closeBtn?.addEventListener('click', () => setDrawerOpen(false));
+        backdrop?.addEventListener('click', () => setDrawerOpen(false));
+        drawerLinks.forEach((a) => a.addEventListener('click', () => setDrawerOpen(false)));
+
+        document.addEventListener('keydown', (e) => {
+          if (!root.classList.contains('drawer-open')) return;
+          if (e.key === 'Escape') setDrawerOpen(false);
+
+          if (e.key === 'Tab') {
+            const drawer = document.getElementById('mobile-drawer');
+            if (!drawer) return;
+            const focusables = Array.from(drawer.querySelectorAll(focusableSelector)).filter(
+              (el) => !el.hasAttribute('disabled') && el.getAttribute('aria-hidden') !== 'true',
+            );
+            if (focusables.length === 0) return;
+            const first = focusables[0];
+            const last = focusables[focusables.length - 1];
+            if (e.shiftKey && document.activeElement === first) {
+              e.preventDefault();
+              last.focus();
+            } else if (!e.shiftKey && document.activeElement === last) {
+              e.preventDefault();
+              first.focus();
+            }
+          }
+        });
